802	  // sandbox-default-ON, and bubblewrap's loopback needs CAP_NET_ADMIN the host lacks → rc=1, no diff.
803	  //
804	  // FIX (gated, bench-scoped, arm-neutral): when PAPERCUSP_XBENCH_BEE_DIRECTIVE is set (the bench launcher
805	  // sets it on the SHARED env both hosts read), every placed `bee` (a) gets that directive APPENDED to its
806	  // brief so — whatever situational overlay the Queen attaches — it claims + implements its lone seeded
807	  // feature, and (b) gets PAPERCUSP_SPAWN_BACKEND/PAPERCUSP_FLEET_SANDBOX pinned PER-SPAWN (the exact
808	  // self-sufficient pins bench-harness-live.ts's `driveToDone` sets) so it runs the real claude/opus backend
809	  // regardless of which process built the spawn command. Only ever active under the bench env flag — normal
810	  // hive/operator spawns are untouched. The Queen's placement/eviction/re-placement/adaptive-wake treatment
811	  // is unchanged: she still decides WHO/WHEN; this only guarantees the bee she places can DO the work.
812	  const benchBeeDirective = role === 'bee' ? (process.env.PAPERCUSP_XBENCH_BEE_DIRECTIVE ?? '').trim() : '';
813	  if (benchBeeDirective) {
814	    // Append the directive when the placer's brief lacks it (the real-Queen arm, whose situational overlay
815	    // never contains it). The FIFO arm's executeBatch already passes the SAME directive as the brief, so
816	    // skip the append there to avoid a duplicate paragraph (idempotent either way).
817	    if (!(input.brief ?? '').includes(benchBeeDirective)) {
818	      input = {
819	        ...input,
820	        brief: input.brief ? `${input.brief}\n\n${benchBeeDirective}` : benchBeeDirective,
821	      };
822	    }
823	    // Pin the bench backend/sandbox per-spawn (self-sufficient, like driveToDone) — every bench bee, not
824	    // only the appended ones — unless the caller already resolved a backend (tier) or explicitly overrode
825	    // these in the process env. Default-on so a spawn built in a host lacking AGENT_CMD/PAPERCUSP_SPAWN_BACKEND
826	    // still runs claude, not omp.
827	    if (!spawnModelBackend && process.env.PAPERCUSP_SPAWN_BACKEND == null) {
828	      extraEnv.PAPERCUSP_SPAWN_BACKEND = 'claude-code';
829	    }
830	    if (process.env.PAPERCUSP_FLEET_SANDBOX == null) {
831	      extraEnv.PAPERCUSP_FLEET_SANDBOX = '0';
832	    }
833	    // BENCH-SCOPED, FAIL-CLOSED OPUS PIN (P-033 Fix 2). Pin THIS bench bee to opus PER-SPAWN via
834	    // PAPERCUSP_SPAWN_MODEL — the highest-precedence model channel (applyRoleModel / invoke.ts resolveModel
835	    // read it FIRST, above the global AGENT_MODELS map + the committed role floor). This makes the opus
836	    // requirement BENCH-SCOPED: only bees under the bench flag are pinned, so non-bench hives keep their
837	    // normal haiku floor (no more GLOBAL AGENT_MODELS opus on :3170 affecting every hive). FAIL-CLOSED:
838	    // the rate-limit governor WAITS on a paused opus bucket rather than substituting, and the model-tiers
839	    // floor-clamp never downgrades below opus — a paused/throttled opus stalls the bench spawn, it never
840	    // silently drops to sonnet/haiku (the provable-opus-only requirement). Skip only if a TIER already
841	    // resolved an explicit per-spawn model (its floor-clamp already governs). Configurable via
842	    // PAPERCUSP_XBENCH_MODEL (default opus:xhigh) so the pin is one knob, not scattered. Skip only when an
843	    // explicit per-spawn modelSpec/tier already resolved (spawnModelSpec) — line below applies it, its own
844	    // floor-clamp governs. (This sets extraEnv; the spawnModelSpec block further down would override it, but
845	    // we guard here to keep the intent explicit and avoid stamping then overwriting.)
846	    if (!spawnModelSpec) {
847	      extraEnv.PAPERCUSP_SPAWN_MODEL = (process.env.PAPERCUSP_XBENCH_MODEL ?? 'opus:xhigh').trim();
848	    }
849	  }
850	  // THE UMBILICAL (voice gap fix): thread the operator's durable `s-…` spawnId into
851	  // the child's env so invoke()/spawn-mcp bakes it as the signed MCP URL's STABLE
852	  // `client=` param. Without this the child minted a fresh random `spawnId` per boot
853	  // AND carried no `client`, so the operator's resolveAgentIdentity() found no
854	  // attributable coord identity and THREW on every coord:send / plans:set-status /
855	  // improvements:capture — the child's file edits landed but it was MUTE on coord.
856	  // The `s-…` id is the SAME owner recorded as `sessionOwner` on the spawned_agents
857	  // row, so a bee's coord messages, its file-lock owner, and fleet:cancel's release
858	  // target all line up. parentSpawnId carries lineage onto the child's MCP URL too.
859	  extraEnv.PAPERCUSP_SPAWN_ID = spawnId;
860	  if (input.parentSpawnId) extraEnv.PAPERCUSP_PARENT_SPAWN_ID = input.parentSpawnId;
861	  // P-050/P-060: thread the Queen brief through the invocation so the invoke-once
862	  // prompt path (invoke.ts → buildPrompt's `## Queen brief` section) injects it into
863	  // the bee's prompt. The brief rides in extraEnv as QUEEN_BRIEF; the child reads
864	  // process.env.QUEEN_BRIEF. (NOTE: the fleet:spawn child does NOT use
865	  // assembleRolePrompt — it goes through invoke-once → buildPrompt; an earlier
866	  // comment naming assembleRolePrompt was the mis-wiring the plan flagged.)
867	  if (input.brief) {
868	    extraEnv.QUEEN_BRIEF = input.brief;
869	  }
870	
871	  // directed-wake-honesty-and-spawn-handoff P-021/P-012: assemble the ONE bounded
872	  // spawn/wake-hydration block (predecessor handoff + hive-roster snapshot +
873	  // work-item carry-note) and thread it via extraEnv.SPAWN_HANDOFF. invoke.ts reads
874	  // it and buildPrompt renders it VERBATIM in the volatile tail (`## Handoff`). This
875	  // is the AUTONOMOUS spawn path's call of the shared seam (the interactive launch
876	  // calls assembleSpawnHydration from bootstrap-role). Gated on
877	  // SPAWN_HANDOFF_HYDRATION (default on). FAIL-SOFT TWICE: each source degrades to
878	  // empty inside assembleSpawnHydration, and this outer guard means a hydration
879	  // failure (flag read, DB hiccup) NEVER blocks the spawn.
880	  try {
881	    if (await getFlag(FLAGS.SPAWN_HANDOFF_HYDRATION, 'system')) {
882	      const hydration = await assembleSpawnHydration({
883	        harness: slug,
884	        featureId: input.featureId ?? undefined,
885	        planSlug: input.planSlug ?? undefined,
886	        // The bee resumes the work-item it was dispatched on; its carry-note is
887	        // keyed by that id (work-item-checkpoint store).
888	        workItemId: input.featureId ?? input.itemId ?? undefined,
889	        workspaceId: input.workspaceId,
890	        ownerId: spawnId,
891	        // B2 deliver-on-spawn (P-023): role drives @role:<role> slot draining;
892	        // ownerId is the delivered_to. nowMs is the drain expiry cutoff.
893	        role,
894	        nowMs: Date.now(),
895	        deps: productionSpawnHydrationDeps(),
896	        log: (m) => console.log(`[operator-spawn] ${spawnId} ${m}`),
897	      });
898	      if (hydration.text) extraEnv.SPAWN_HANDOFF = hydration.text;
899	    }
900	  } catch (err) {
901	    // fail-soft: hydration is additive context, never a spawn blocker.
902	    console.warn(
903	      `[operator-spawn] ${spawnId}: spawn-handoff hydration failed (degraded, spawn continues): ${err instanceof Error ? err.message : String(err)}`,
904	    );
905	  }
906	
907	  // Per-spawn model escalation: buildInvokeOnce reads this to apply `--model`/
908	  // `--effort` to THIS child's command (outranking AGENT_MODELS + the committed
909	  // default), and the child's own invoke.ts resolveModel consults it first —
910	  // covering the aiBackend agentCmd-swap path the command-level append can't reach.
911	  if (spawnModelSpec) {
912	    extraEnv.PAPERCUSP_SPAWN_MODEL = spawnModelSpec;
913	  }
914	  // Per-tier backend: buildInvokeOnce swaps the base command to this backend's
915	  // default and pins the child's AGENT_BACKEND to match.
916	  if (spawnModelBackend) {
917	    extraEnv.PAPERCUSP_SPAWN_BACKEND = spawnModelBackend;
918	  }
919	
920	  // P-012 (hive-inference-gateway): when the INFERENCE_GATEWAY flag is ON (default OFF),
921	  // point this bee at the localhost pacing gateway (ANTHROPIC_BASE_URL=127.0.0.1:<port>) so
922	  // it egresses through ONE bound account paced against the unified 5h/7d budget (D-009)
923	  // instead of bursting blind. The bee keeps its ~/.claude credential symlink (the gateway
924	  // strips + reinjects auth), so flag-OFF instantly reverts to direct egress. Fails CLOSED:
925	  // if the gateway service is down the bee's request is refused rather than bursting direct.
926	  // P-004 (multi-credential routing): when INFERENCE_GATEWAY_MULTI_ACCOUNT is ALSO on, pin this bee
927	  // to a pool account (sticky → harness-pin → 5h-budget drain) via ANTHROPIC_CUSTOM_HEADERS, so its
928	  // per-credential conversation cache survives and the aggregate Max budget across subscriptions
929	  // stays filled (D-003). Fail-soft: any error → no header → the gateway routes to its active()
930	  // account (today's single-credential behavior).
931	  const gwOn = await getFlag(FLAGS.INFERENCE_GATEWAY, 'system');
932	  let routeAccountId: string | undefined;
933	  if (gwOn && (await getFlag(FLAGS.INFERENCE_GATEWAY_MULTI_ACCOUNT, 'system'))) {
934	    routeAccountId = await selectSpawnAccount(input.workspaceId, slug).catch(() => undefined);
935	  }
936	  Object.assign(extraEnv, gatewaySpawnEnv(gwOn, { accountId: routeAccountId }));
937	  // account-aware-rate-governor-routing Phase 1: run the bee UNDER the selected account so the
938	  // spawn-side governor (orchestrator-runner) keys its rate bucket PER-ACCOUNT
939	  // (`anthropic:opus@<id>`) instead of the account-blind global `anthropic:opus`. Without this a
940	  // single account's 429 pauses the class bucket and freezes EVERY opus spawn even while other
941	  // accounts sit idle (owner's "rate-limit-with-headroom = routing bug"). selectSpawnAccount only
942	  // ever returns an AVAILABLE account, so the keyed per-account bucket admits.
943	  if (routeAccountId) extraEnv.PAPERCUSP_ACCOUNT_ID = routeAccountId;
944	
945	  // Register an abort handle so fleet:cancel can stop the child (EI-40).
946	  const abort = new AbortController();
947	  localSpawnAborts.set(spawnId, abort);
948	  ensureSpawnHeartbeatLoop();
949	
950	  // Fire-and-forget: the spawn returns now; completion lands on the nursery row.
951	  let finalStatus: 'done' | 'failed' | 'cancelled' | null = null;
952	  void spawnInvokeOnce(project.path, role, extras, extraEnv, {
953	    signal: abort.signal,
954	    forceSessionId,
955	    ...(input.timeoutMs ? { timeoutMs: input.timeoutMs } : {}),
956	    // EI-85: record the child OS pid + this host so the reclaim sweep can
957	    // /proc-liveness-check the process instead of mislabeling a stale-heartbeat
958	    // row (host briefly paused) as a dead child. Best-effort — a missed write
959	    // just degrades to the heartbeat-stale reclaim.
960	    onChildPid: (pid) => {
961	      void recordSpawnPid(getOrgPg().sql, spawnId, pid).catch(() => {});
962	    },
963	    // P-008: per-chunk stream signal, persisted by the heartbeat tick.
964	    onOutputActivity: () => noteSpawnOutput(spawnId),
965	  })
966	    .then(async (r) => {
967	      finalStatus = abort.signal.aborted ? 'cancelled' : (r.exitCode === 0 ? 'done' : 'failed');
968	      // WI-222: post-bee-exit work-item completion safety net. A bee placed on a
969	      // feature that claimed it (→ in_progress), implemented + committed, and exited
970	      // rc=0 WITHOUT landing work_items:complete leaves the feature non-terminal — the
971	      // placement-watchdog then re-places the dead-holder/non-terminal unit until the
972	      // cursed breaker trips. The DBOS pipeline closes this loop on its terminal DONE
973	      // (reconcileDoneStatus), but that path never runs for hive members, so settle it
974	      // here with the SAME conservative guard (in_progress/validating → passed only;
975	      // never force-pass todo/failing/deprecated). The predicate no-ops every non-bee /
976	      // crashed / cancelled / featureless exit; the call is best-effort (never throws).
977	      await maybeReconcileBeeCompletion(
978	        {
979	          role,
980	          exitCode: r.exitCode,
981	          aborted: abort.signal.aborted,
982	          featureId: input.featureId,
983	          harnessSlug: slug,
984	          workspaceId: input.workspaceId,
985	        },
986	        { log: (m) => console.log(`[operator-spawn] ${spawnId} ${m}`) },
987	      );
988	      return finishSpawn(sql, {
989	        spawnId,
990	        workspaceId: input.workspaceId,
991	        status: finalStatus,
992	        exitCode: r.exitCode,
993	        errorMessage: (r.stderr || '').slice(-2000) || null,
994	        outputTail: (r.output || '').slice(-2000) || null,
995	      });
996	    })
997	    .catch((err) => {
998	      finalStatus = abort.signal.aborted ? 'cancelled' : 'failed';
999	      return finishSpawn(sql, {
1000	        spawnId,
1001	        workspaceId: input.workspaceId,
1002	        status: finalStatus,
1003	        errorMessage: err instanceof Error ? err.message : String(err),
1004	      }).catch(() => { /* PG down — nothing left to record to */ });
1005	    })
1006	    .finally(() => {
1007	      localSpawnAborts.delete(spawnId);
1008	      localSpawnOutput.delete(spawnId);
1009	      // The terminal flip above freed a ceiling slot — wake any over-ceiling
1010	      // waiter sleeping on the slot key (D-004). Best-effort, off the hot path.
1011	      void announceSpawnSlotFreed(input.workspaceId, `spawn ${spawnId} finished — ceiling slot freed`);
1012	      // EI-108: Wake parent on child death (if the spawn has a parent)
1013	      if (finalStatus) {
1014	        void wakeParentOnChildDeath(sql, spawnId, input.workspaceId, finalStatus).catch(() => {
1015	          /* best-effort — logged inside wakeParentOnChildDeath */
1016	        });
1017	      }
1018	    });
1019	
1020	  return { ok: true, spawnId, harness: slug, projectDir: project.path, error: null };
1021	}
